(()=>{
const storage='cicluz-location-tree-v1';let tree=[];try{tree=JSON.parse(localStorage.getItem(storage)||'[]')}catch{}
const levels=['Área','Setor','Local','Sublocal'];const colors=['#7c3aed','#eab308','#ef4444','#f97316','#22c55e','#2563eb'];const paths=[icons.groups,icons.overview,icons.team,icons.records,icons.settings,...Object.values(jobIcons).map(svg=>svg.replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')),...Object.values(icons)];
const previous=showConfig;showConfig=function(type,origin){if(type!=='area')return previous(type,origin);showLocationTree(origin)};
function showLocationTree(origin){const view=document.getElementById('sector-view'),box=document.getElementById('sector-content');view.classList.remove('financial-groups','account-orange');view.style.setProperty('--menu-accent','#7c3aed');view.querySelector('.panel').style.setProperty('--panel-color','#7c3aed');document.getElementById('sector-title').textContent='Área / Setor / Local';document.getElementById('sector-path').textContent='Configurações / '+origin+' / Área / Setor / Local';view.querySelectorAll('.view-alphabetize,.financial-expand-all,.location-tool').forEach(el=>el.remove());setSectorBack(()=>openSection(sections[6][0],'Gestão de Pessoas','people-settings','#7c3aed'));box.replaceChildren();const opened=new Set();
const button=(label,fn,cls='btn secondary')=>{const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=label;b.onclick=fn;return b};
function save(){try{localStorage.setItem(storage,JSON.stringify(tree));return true}catch{alert('Não foi possível salvar neste navegador.');return false}}
const addButton=(label,fn)=>{const b=button('+ '+label.replace(/^Adicionar (área)$/,'Nova $1').replace(/^Adicionar /,'Novo '),fn,'btn tree-add-solid location-add');b.title=label;b.setAttribute('aria-label',label);return b};
const toolbar=document.createElement('div');toolbar.className='location-toolbar';toolbar.append(addButton('Adicionar área',()=>editor(null,tree,1)));box.append(toolbar);const list=document.createElement('div');list.className='location-tree';box.append(list,toolbar);
const sort=createAlphabetizeButton(()=>{const order=pool=>{pool.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR',{numeric:true,sensitivity:'base'}));pool.forEach(n=>order(n.children))};order(tree);save();render()});sort.classList.add('location-tool');mountAlphabetizeButton(view,sort);
for(const [label,path,open] of [['Expandir todos','m5 9 7 7 7-7',true],['Recolher todos','m5 15 7-7 7 7',false]]){const b=button('',()=>{opened.clear();if(open){const walk=pool=>pool.forEach(n=>{opened.add(n.id);walk(n.children)});walk(tree)}render()},'shortcut-circle location-tool');b.title=label;b.setAttribute('aria-label',label);b.innerHTML='<svg viewBox="0 0 24 24"><path d="'+path+'"/></svg>';view.querySelector('.shortcut-actions').append(b)}normalizeHeaderActions(view);
function render(){list.replaceChildren();if(!tree.length){const p=document.createElement('p');p.textContent='Crie áreas e acrescente setores, locais e sublocais.';list.append(p)}draw(tree,list,1)}
function draw(pool,container,level){for(const node of pool){const wrap=document.createElement('div');wrap.className='location-node';wrap.dataset.id=node.id;const row=document.createElement('div');row.className='location-row';row.style.setProperty('--node-color',node.color);const move=button('⠿',()=>{},'location-move menu-item-move');move.title='Arraste para organizar';move.setAttribute('aria-label','Mover '+node.name);move.style.touchAction='none';enableContinuousReorder(move,{item:wrap,items:()=>[...container.children].filter(el=>el.classList.contains('location-node')),onCommit:()=>{const ids=[...container.children].filter(el=>el.classList.contains('location-node')).map(el=>el.dataset.id);pool.sort((a,b)=>ids.indexOf(a.id)-ids.indexOf(b.id));save()}});move.onkeydown=e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const i=pool.indexOf(node),j=i+(e.key==='ArrowUp'?-1:1);if(j<0||j>=pool.length)return;pool.splice(i,1);pool.splice(j,0,node);save();render()};const icon=document.createElement('span');icon.className='location-icon';icon.innerHTML='<svg viewBox="0 0 24 24">'+paths[node.icon||0]+'</svg>';const title=button(node.name,()=>{opened.has(node.id)?opened.delete(node.id):opened.add(node.id);render()},'location-name');const expand=button(opened.has(node.id)?'⌄':'›',()=>title.click(),'location-expand');expand.setAttribute('aria-label','Expandir ou recolher '+node.name);expand.setAttribute('aria-expanded',String(opened.has(node.id)));const copy=document.createElement('span');copy.className='location-copy';copy.append(title);if(level<4){const count=document.createElement('small');count.className='financial-count location-count';const labels=[null,['setor','setores'],['local','locais'],['sublocal','sublocais']];count.textContent=node.children.length+' '+labels[level][node.children.length===1?0:1];copy.append(count)}row.append(move);if(node.children.length)row.append(expand);row.append(icon,copy);const {arrow,actions}=createFinancialActions({label:node.name,container:list,onEdit:()=>editor(node,pool,level),onDelete:()=>{const remove=actions.querySelector('button');if(remove.dataset.confirm!=='yes'){remove.dataset.confirm='yes';remove.title='Confirmar exclusão';remove.setAttribute('aria-label','Confirmar exclusão de '+node.name);remove.innerHTML='<span aria-hidden="true">✓</span>';return}pool.splice(pool.indexOf(node),1);save();render()}});row.append(arrow,actions);wrap.append(row);if(opened.has(node.id)||!node.children.length){const children=document.createElement('div');children.className='location-children';draw(node.children,children,level+1);if(level<4){const addRow=document.createElement('div');addRow.className='location-add-row';addRow.append(addButton('Adicionar '+levels[level],()=>editor(null,node.children,level+1,node)));children.append(addRow)}wrap.append(children)}container.append(wrap)}}
function editor(node,pool,level,parent){const dialog=document.createElement('dialog');dialog.className='location-dialog';const form=document.createElement('form');const heading=document.createElement('h3');heading.textContent=(node?'Editar ':'Cadastrar ')+levels[level-1];const label=document.createElement('label');label.textContent='Nome';const name=document.createElement('input');name.required=true;name.maxLength=120;name.value=node?.name||'';label.append(name);const colorLabel=document.createElement('label');colorLabel.textContent='Cor';const color=document.createElement('input');color.type='color';color.value=node?.color||parent?.color||colors[0];color.setAttribute('aria-label','Cor personalizada');const palette=document.createElement('div');palette.className='location-palette';const swatches=['#000000','#434343','#666666','#999999','#b7b7b7','#cccccc','#eeeeee','#ffffff','#ef4444','#f97316','#eab308','#22c55e','#06b6d4','#2563eb','#7c3aed','#db2777','#fecaca','#fed7aa','#fef08a','#bbf7d0','#a5f3fc','#bfdbfe','#ddd6fe','#fbcfe8','#fca5a5','#fdba74','#fde047','#86efac','#67e8f9','#93c5fd','#c4b5fd','#f9a8d4','#b91c1c','#c2410c','#a16207','#15803d','#0e7490','#1d4ed8','#6d28d9','#be185d','#7f1d1d','#7c2d12','#713f12','#14532d','#164e63','#1e3a8a','#4c1d95','#831843'];for(const hex of swatches){const swatch=button('',()=>{color.value=hex;refresh()},'location-swatch');swatch.style.background=hex;swatch.title=hex;swatch.setAttribute('aria-label','Cor '+hex);swatch.dataset.color=hex;palette.append(swatch)}const custom=document.createElement('span');custom.className='location-custom-color';custom.append(document.createTextNode('Cor personalizada'),color);const paletteDetails=document.createElement('details');paletteDetails.className='location-color-picker';const paletteSummary=document.createElement('summary');const colorChip=document.createElement('span');colorChip.className='location-color-chip';paletteSummary.append(colorChip,document.createTextNode('Escolher cor'));paletteDetails.append(paletteSummary,palette,custom);colorLabel.append(paletteDetails);const choice=document.createElement('div');choice.className='location-icon-options';let selected=node?.icon||0;const preview=document.createElement('div');preview.className='location-preview location-preview-card';function refresh(){palette.querySelectorAll('button').forEach(b=>{const active=b.dataset.color===color.value;b.setAttribute('aria-pressed',String(active));b.textContent=active?'✓':''});colorChip.style.background=color.value;preview.style.setProperty('--node-color',color.value);preview.innerHTML='<span class="location-preview-handle" aria-hidden="true">⠿</span><span class="location-icon"><svg viewBox="0 0 24 24">'+paths[selected]+'</svg></span>';const previewText=document.createElement('span');previewText.className='location-preview-name';previewText.textContent=name.value||'Nome da '+levels[level-1].toLocaleLowerCase('pt-BR');const previewArrow=document.createElement('span');previewArrow.className='location-preview-arrow';previewArrow.textContent='›';preview.append(previewText,previewArrow);[...choice.querySelectorAll('button')].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===selected)))}paths.forEach((p,i)=>{const b=button('',()=>{selected=i;refresh()},'shortcut-circle');b.title='Ícone '+(i+1);b.setAttribute('aria-label',b.title);b.innerHTML='<svg viewBox="0 0 24 24">'+p+'</svg>';choice.append(b)});const more=document.createElement('details');more.className='location-more-icons';const moreTitle=document.createElement('summary');moreTitle.textContent='Mais ícones';const gallery=document.createElement('div');gallery.className='location-icon-options';more.append(moreTitle,gallery);if(selected>=5)more.open=true;name.oninput=()=>{name.setCustomValidity('');refresh()};color.onchange=refresh;[...choice.children].slice(5).forEach(b=>gallery.append(b));choice.append(more);const actions=document.createElement('div');actions.className='actions';const submit=document.createElement('button');submit.type='submit';submit.className='btn';submit.textContent='Salvar';actions.append(submit,button('Cancelar',()=>dialog.close()));const header=document.createElement('div');header.className='location-dialog-header';const headIcon=document.createElement('span');headIcon.className='location-icon';headIcon.innerHTML='<svg viewBox="0 0 24 24">'+paths[node?.icon||0]+'</svg>';const tools=document.createElement('div');tools.className='location-dialog-tools';for(const [title,path] of [['Voltar','m14 6-6 6 6 6'],['Fechar','m6 6 12 12M18 6 6 18']]){const action=button('',()=>dialog.close(),'shortcut-circle');action.title=title;action.setAttribute('aria-label',title);action.innerHTML='<svg viewBox="0 0 24 24"><path d="'+path+'"/></svg>';tools.append(action)}header.append(headIcon,heading,tools);const identity=document.createElement('div');identity.className='job-identity location-identity';const iconField=document.createElement('div');const iconTitle=document.createElement('span');iconTitle.textContent='Ícone';iconField.append(iconTitle,choice);identity.append(label,iconField);form.append(header,identity,colorLabel,preview,actions);form.onsubmit=e=>{e.preventDefault();const value=name.value.trim();if(!value)return;if(pool.some(n=>n!==node&&n.name.toLocaleLowerCase('pt-BR')===value.toLocaleLowerCase('pt-BR'))){name.setCustomValidity('Este nome já existe neste nível.');name.reportValidity();return}if(node)Object.assign(node,{name:value,color:color.value,icon:selected});else pool.push({id:crypto.randomUUID(),name:value,color:color.value,icon:selected,children:[]});if(parent)opened.add(parent.id);if(save()){dialog.close();render()}};dialog.append(form);document.body.append(dialog);dialog.onclose=()=>dialog.remove();refresh();dialog.showModal();name.focus()}
render()}
})();
